import {readFile,writeFile} from 'node:fs/promises';
const read=async p=>JSON.parse(await readFile(p,'utf8'));
const date='2026-10-30',base='data/dev/source-archives/audit-0900-'+date;
const [g,ledger,editorial,watchlist,connector]=await Promise.all(['data/dev/github-radar-latest.json','data/dev/github-radar-review-ledger.json','data/dev/github-editorial-review-2026-10-30.json','github-industry-watchlist.json',base+'/github-mandatory-connector.json'].map(read));
const sdk=editorial.repositories.find(r=>r.repo==='Factory-AI/droid-sdk-typescript');
Object.assign(sdk,{name:'Droid SDK 工程样例',category:'Agent 工程 / 官方 SDK 样例',summary:'Factory官方Droid SDK指南与可运行集成样例，含Node/浏览器示例执行器、MCP测试服务与文档片段校验工具；SDK包本体作为依赖分发。',originality:'official_runnable_integration_examples_and_validation_harness',decisionReason:'实际package.json将本库标为@factory/droid-sdk-examples，依赖@factory/droid-sdk；examples与scripts提供官方原创集成和校验工程，按工程参考B级收录，不宣称SDK本体源码仓库。'});
const byRepo=new Map(editorial.repositories.map(r=>[r.repo.toLowerCase(),r]));
for(const records of [g.projects,watchlist.repositories,g.verificationSummary.mandatoryReviewed,g.verificationSummary.watchSamples])for(const row of records){const e=byRepo.get(row.repo.toLowerCase());if(!e)continue;const metadataLicense=row.license;for(const key of ['name','category','summary','riskNote','industryFit','priorityDomains','originality','officialRelationship','decisionReason','intakeDecision','license'])if(e[key]!==undefined)row[key]=e[key];row.editorialEvidence='data/dev/github-editorial-review-2026-10-30.json';row.licenseReview={checkedAt:editorial.checkedAt,metadataLicense,method:'Actual official LICENSE read; API NOASSERTION is retained as original metadata evidence.',evidence:base+'/github-new-licenses.json'};}
ledger.mandatoryReviewed=g.verificationSummary.mandatoryReviewed;
ledger.watchSamples=g.verificationSummary.watchSamples;
g.run.audit0900={checkedAt:new Date().toISOString(),connectorVerified:connector.filter(r=>r.success).length,mandatory:g.verificationSummary.coverage.mandatory,newFormalRepositories:editorial.repositories.map(r=>r.repo),sourceEvidence:base,notes:['All mandatory official README/commits/Issues/PR/Releases checked after current AI bridge.','Actual LICENSE resolves NOASSERTION for Hy-Nomas, E0.5 and Droid examples; metadata preserved separately.','Droid repo is official SDK examples and harness tooling, not SDK implementation source.']};
const esc=s=>String(s??'').replaceAll('|','\\|').replaceAll('\n',' '),labels={approved:'收录',observe:'观察',rejected:'拒绝'};
for(const p of [`reports/github-radar-${date}.md`,`public/reports/github-radar-${date}.md`]){let text=await readFile(p,'utf8');for(const row of ledger.mandatoryReviewed){const prefix=`| [${row.repo}](https://github.com/${row.repo}) |`;const value=`${prefix} ${esc(row.queue)} | ${row.stars} / ${row.forks} | ${esc(row.lastCommit)} | ${esc(row.release)} | ${esc(row.license)} | ${row.readmeVerified?'是':'否'} / ${row.demoOrInstall?'是':'否'} | ${row.issuesVerified?'是':'否'} / ${row.pullRequestsVerified?'是':'否'} | ${row.accessible?'可访问':'不可访问'}；${row.archived?'已归档':'未归档'}；${row.fork?'Fork':'非 Fork'} | **${labels[row.intakeDecision]}**：${esc(row.decisionReason)} |`;text=text.split('\n').map(line=>line.startsWith(prefix)?value:line).join('\n');}text+='\n## 二次审计与新增收录\n\n当前AI提及的6个官方仓库已分别核对README、目录、许可与维护元数据。Droid仓库为官方可运行SDK样例与校验工具，并非SDK本体源码。Hy-Nomas、E0.5及Droid的API许可标记为NOASSERTION，实际LICENSE正文已独立核对并保留元数据原值。全部当日必核仓库的官方页面证据完整；可选OSS Insight状态保持真实。\n';await writeFile(p,text);}
for(const [p,d] of [['data/dev/github-radar-latest.json',g],['data/dev/github-radar-review-ledger.json',ledger],['data/dev/github-editorial-review-2026-10-30.json',editorial],['github-industry-watchlist.json',watchlist]])await writeFile(p,JSON.stringify(d,null,2)+'\n');
console.log(JSON.stringify(g.run.audit0900));
